export type LanguageCode = 'en-GB' | 'es-ES' | 'es-AR' | 'pt-BR' | 'fr-FR';

export interface LanguageInfo {
  code: LanguageCode;
  name: string;
  nativeName: string;
  flag: string;
  region: string;
}

export const LANGUAGES: Record<LanguageCode, LanguageInfo> = {
  'en-GB': {
    code: 'en-GB',
    name: 'British English',
    nativeName: 'English (UK)',
    flag: '🇬🇧',
    region: 'United Kingdom',
  },
  'es-ES': {
    code: 'es-ES',
    name: 'Castilian Spanish',
    nativeName: 'Español (España)',
    flag: '🇪🇸',
    region: 'España',
  },
  'es-AR': {
    code: 'es-AR',
    name: 'Argentine Spanish',
    nativeName: 'Español (Argentina)',
    flag: '🇦🇷',
    region: 'Argentina & Cono Sur',
  },
  'pt-BR': {
    code: 'pt-BR',
    name: 'Brazilian Portuguese',
    nativeName: 'Português (Brasil)',
    flag: '🇧🇷',
    region: 'Brasil',
  },
  'fr-FR': {
    code: 'fr-FR',
    name: 'French',
    nativeName: 'Français',
    flag: '🇫🇷',
    region: 'France',
  },
};

import { safeGetItem, safeSetItem } from './storageCleaner';
import { autoTranslateText } from './autoTranslationEngine';
import { getProfileStorageKey, getActiveProfile, updateProfile } from './profileSystem';

const STORAGE_KEY = 'FOOTBALL_CAREER_LANGUAGE_V1';

let currentLanguage: LanguageCode = 'es-ES';

// Try to initialize language from active profile or localStorage
try {
  const prof = getActiveProfile();
  if (prof && prof.selectedLanguage && (prof.selectedLanguage in LANGUAGES)) {
    currentLanguage = prof.selectedLanguage as LanguageCode;
  } else {
    const saved = safeGetItem(getProfileStorageKey(STORAGE_KEY)) || safeGetItem(STORAGE_KEY);
    if (saved && (saved in LANGUAGES)) {
      currentLanguage = saved as LanguageCode;
    } else {
      currentLanguage = 'es-ES';
    }
  }
} catch (e) {
  console.warn('Could not read stored language preference:', e);
  currentLanguage = 'es-ES';
}

// Subscribers listener list for active reactive re-renders
type LanguageChangeListener = (lang: LanguageCode) => void;
const listeners: Set<LanguageChangeListener> = new Set();

export function reloadLanguageFromProfile(): void {
  const profile = getActiveProfile();
  let targetLang: LanguageCode = currentLanguage;
  if (profile && profile.selectedLanguage && (profile.selectedLanguage in LANGUAGES)) {
    targetLang = profile.selectedLanguage as LanguageCode;
  } else {
    try {
      const saved = safeGetItem(getProfileStorageKey(STORAGE_KEY));
      if (saved && (saved in LANGUAGES)) {
        targetLang = saved as LanguageCode;
      }
    } catch {}
  }
  if (targetLang !== currentLanguage) {
    currentLanguage = targetLang;
    listeners.forEach((listener) => {
      try {
        listener(currentLanguage);
      } catch {}
    });
  }
}

if (typeof window !== 'undefined') {
  window.addEventListener('drawstar_profile_switched', reloadLanguageFromProfile);
}

export function getStoredLanguage(): LanguageCode {
  return currentLanguage;
}

export function setStoredLanguage(code: LanguageCode): void {
  if (code in LANGUAGES && code !== currentLanguage) {
    currentLanguage = code;
    try {
      safeSetItem(getProfileStorageKey(STORAGE_KEY), code);
      safeSetItem(STORAGE_KEY, code);
      const activeProf = getActiveProfile();
      if (activeProf && activeProf.selectedLanguage !== code) {
        updateProfile(activeProf.id, { selectedLanguage: code });
      }
    } catch (e) {
      console.warn('Could not save language preference:', e);
    }
    listeners.forEach((listener) => listener(currentLanguage));
  }
}

export function subscribeLanguageChange(listener: LanguageChangeListener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

