    'Maximum immersion — step onto the pitch for every single match.': 'Máxima inmersión — pisá la cancha en todos y cada uno de los partidos.',
    'Every Definitive, Important, and Regular match triggers the interactive Key Match experience. Perfect for players who want to build their career match-by-match.': 'Cada partido Definitivo, Importante y Regular activa la experiencia interactiva de Partido Clave. Ideal para quienes quieren armar su carrera partido a partido.',
    'Play all 18+ league matches per season': 'Jugá todos los más de 18 partidos de liga por temporada',
