    'Definitive + Important (1 & 2)': 'Definitivos + Importantes (1 y 2)',
    'The ideal balance — play finals, title deciders, semi-finals & iconic derbies.': 'El balance ideal — jugá finales, definiciones de título, semis y clásicos históricos.',
    'Play all Definitive Finals, Title Clinchers, Relegation battles, Semi-Finals, 1st vs 2nd table clashes, and traditional Derbies (El Clásico, Madrid Derby, London Derby, Superclásico). Standard matches are auto-simulated.': 'Jugá todas las Finales Definitivas, definiciones de campeonato, peleas por la permanencia, semifinales, duelos 1° vs 2° y clásicos históricos (El Clásico, Superclásico, etc.). Los partidos comunes se simulan solos.',
