    '~30% High Stakes': '~30% Partidos Picantes',
    'Finals Only': 'Solo Finales',
    'Definitive Only (1)': 'Solo Definitivos (1)',
    'Fast-paced career — play only the matches that decide major silverware or survival.': 'Carrera rápida — jugá únicamente los partidos que definen títulos importantes o la permanencia.',
    'Only matches that directly determine a trophy, championship title, promotion, or relegation are played as Key Matches. All regular league games, derbies, and semi-finals are simulated.': 'Solo los partidos que definen directamente una copa, título, ascenso o descenso se juegan como Partidos Clave. Los demás partidos de liga, clásicos y semifinales se simulan.',
