export function translateNationality(nat: string | undefined): string {
  if (!nat) return '';
  const activePacket = getActiveLanguagePacket();
  if (!activePacket || !activePacket.translations) return '';
  const key = `NAT_${nat.toUpperCase().replace(/\s+/g, '_')}`;
  return activePacket.translations[key] || activePacket.translations[nat] || '';
}

export function translateFoot(foot: string | undefined): string {
  if (!foot) return '';
  const activePacket = getActiveLanguagePacket();
  if (!activePacket || !activePacket.translations) return '';
  const lower = foot.toLowerCase().trim();
  if (lower.startsWith('right')) return activePacket.translations['Right'] || activePacket.translations['FOOT_RIGHT'] || '';
  if (lower.startsWith('left')) return activePacket.translations['Left'] || activePacket.translations['FOOT_LEFT'] || '';
  if (lower.startsWith('both')) return activePacket.translations['Both'] || activePacket.translations['FOOT_BOTH'] || '';
  return activePacket.translations[foot] || '';
}

export function translatePosition(pos: string | undefined): string {
  if (!pos) return '';
  const activePacket = getActiveLanguagePacket();
  if (!activePacket || !activePacket.translations) return '';
  const upper = pos.toUpperCase();
  return activePacket.translations[`POS_${upper}`] || activePacket.translations[`SUBPOS_${pos.toLowerCase()}`] || activePacket.translations[pos] || '';
}

export function translatePlaystyle(style: string | undefined): string {
  if (!style) return '';
  const activePacket = getActiveLanguagePacket();
  if (!activePacket || !activePacket.translations) return '';
  const key = `PLAYSTYLE_${style.toUpperCase().replace(/\s+/g, '_')}`;
  return activePacket.translations[key] || activePacket.translations[style] || '';
}

export function translateStatLabel(key: string): string {
  if (!key) return '';
  const activePacket = getActiveLanguagePacket();
  if (!activePacket || !activePacket.translations) return '';
  const abbr = key.toUpperCase();
  if (activePacket.translations[`ABBR_${abbr}`]) return activePacket.translations[`ABBR_${abbr}`];
  if (activePacket.translations[`ATTR_${abbr}`]) return activePacket.translations[`ATTR_${abbr}`];
  if (activePacket.translations[`STAT_${abbr}`]) return activePacket.translations[`STAT_${abbr}`];
  return activePacket.translations[key] || '';
}

export function translateStoreItem(item: { id: string; name: string; description: string; effectSummary?: string; effect?: string }) {
  const activePacket = getActiveLanguagePacket();
  if (!activePacket || !activePacket.translations) {
    return { name: '', description: '', effect: '' };
  }
  const tr = activePacket.translations;
  return {
    name: tr[`STORE_ITEM_${item.id}_NAME`] || tr[`${item.id}:name`] || tr[item.name] || '',
    description: tr[`STORE_ITEM_${item.id}_DESC`] || tr[`${item.id}:desc`] || tr[item.description] || '',
    effect: tr[`STORE_ITEM_${item.id}_EFFECT`] || tr[`${item.id}:effect`] || tr[item.effectSummary || item.effect || ''] || '',
  };
}

export function translateBusiness(biz: { id: string; name: string; category: string; description: string }) {
  const activePacket = getActiveLanguagePacket();
  if (!activePacket || !activePacket.translations) {
    return { name: '', category: '', description: '' };
  }
  const tr = activePacket.translations;
  return {
    name: tr[`BIZ_${biz.id}_NAME`] || tr[`${biz.id}:name`] || tr[biz.name] || '',
    category: tr[`BIZ_${biz.id}_CAT`] || tr[biz.category] || '',
    description: tr[`BIZ_${biz.id}_DESC`] || tr[`${biz.id}:desc`] || tr[biz.description] || '',
  };
}

export function translatePerk(perk: { id: string; name: string; shortDescription: string; effect: string; howToObtain: string; storyTitle?: string; storyNarrative?: string }) {
  const activePacket = getActiveLanguagePacket();
  if (!activePacket || !activePacket.translations) {
    return { name: '', shortDescription: '', effect: '', howToObtain: '', storyTitle: '', storyNarrative: '' };
  }
  const tr = activePacket.translations;
  return {
    name: tr[`PERK_${perk.id}_NAME`] || tr[`${perk.id}:name`] || tr[perk.name] || '',
    shortDescription: tr[`PERK_${perk.id}_SHORT_DESC`] || tr[`${perk.id}:desc`] || tr[perk.shortDescription] || '',
    effect: tr[`PERK_${perk.id}_EFFECT`] || tr[`${perk.id}:effect`] || tr[perk.effect] || '',
    howToObtain: tr[`PERK_${perk.id}_OBTAIN`] || tr[perk.howToObtain] || '',
    storyTitle: tr[`PERK_${perk.id}_STORY_TITLE`] || tr[perk.storyTitle || ''] || '',
    storyNarrative: tr[`PERK_${perk.id}_STORY_NARRATIVE`] || tr[perk.storyNarrative || ''] || '',
  };
}


export function translateBio(customBio?: string, name: string = 'The player', position: string = 'ST', club: string = 'FC Barcelona'): string {
  if (customBio) {
    if (customBio.includes('promising young prospect')) {
      switch (currentLanguage) {
        case 'es-ES': return 'Una joven promesa que da sus primeros pasos en el fútbol profesional. ¡Alto potencial de crecimiento!';
        case 'es-AR': return 'Un pibe con un futuro enorme dando sus primeros pasos en el fútbol profesional. ¡Potencial tremendo!';
        case 'pt-BR': return 'Uma jovem promessa dando seus primeiros passos no futebol profissional. Alto potencial de evolução!';
        case 'fr-FR': return 'Un jeune espoir prometteur qui fait ses premiers pas dans le football professionnel. Fort potentiel !';
        default: return customBio;
      }
    }
    if (customBio.includes('is an elite footballer currently playing as')) {
      const posTr = translatePosition(position);
      switch (currentLanguage) {
        case 'es-ES': return `${name} es un futbolista de élite que actualmente juega como ${posTr} en el ${club}.`;
        case 'es-AR': return `${name} es un jugador de élite que juega como ${posTr} en ${club}.`;
        case 'pt-BR': return `${name} é um jogador de elite que atualmente joga como ${posTr} no ${club}.`;
        case 'fr-FR': return `${name} est un joueur d'élite évoluant au poste de ${posTr} au ${club}.`;
        default: return `${name} is an elite footballer currently playing as ${position} for ${club}.`;
      }
    }
    return customBio;
  }
  const posTr = translatePosition(position);
  switch (currentLanguage) {
    case 'es-ES': return `${name} es un futbolista de élite que actualmente juega como ${posTr} en el ${club}.`;
    case 'es-AR': return `${name} es un jugador de élite que juega como ${posTr} en ${club}.`;
    case 'pt-BR': return `${name} é um jogador de elite que atualmente joga como ${posTr} no ${club}.`;
    case 'fr-FR': return `${name} est un joueur d'élite évoluant au poste de ${posTr} au ${club}.`;
    default: return `${name} is an elite footballer currently playing as ${position} for ${club}.`;
  }
}

/**
 * LOCALIZED DYNAMIC GENERATORS
 * Strictly preserves Proper Names (Team names, City names, Competition names, Player names)
 * while localizing surrounding narrative sentences in all 5 languages.
 */

export function generateLocalizedTransferOfferMessage(
  teamName: string,
  feeAmountStr: string,
  weeklyWageStr: string
): string {
  switch (currentLanguage) {
    case 'es-ES':
      return `¡El ${teamName} ha presentado una oferta de traspaso oficial por valor de ${feeAmountStr} con un sueldo de ${weeklyWageStr}/sem!`;
    case 'es-AR':
      return `¡El ${teamName} presentó una oferta de transferencia por ${feeAmountStr} y un contrato de ${weeklyWageStr} por semana!`;
    case 'pt-BR':
      return `O ${teamName} apresentou uma proposta de transferência oficial de ${feeAmountStr} com salário de ${weeklyWageStr}/sem!`;
    case 'fr-FR':
      return `Le club de ${teamName} a transmis une offre de transfert officielle de ${feeAmountStr} avec un salaire de ${weeklyWageStr}/sem !`;
    case 'en-GB':
    default:
      return `${teamName} have submitted an official transfer offer worth ${feeAmountStr} with weekly wages of ${weeklyWageStr}!`;
  }
}

export function generateLocalizedContractOfferMessage(
  teamName: string,
  wageStr: string,
  years: number
): string {
  switch (currentLanguage) {
    case 'es-ES':
      return `${teamName} te ofrece un nuevo contrato por ${years} año(s) con una ficha de ${wageStr} semanales.`;
    case 'es-AR':
      return `${teamName} te ofrece un contrato nuevo por ${years} año(s) con un sueldo de ${wageStr} por semana.`;
    case 'pt-BR':
      return `O ${teamName} ofereceu um novo contrato de ${years} ano(s) com salário de ${wageStr} semanais.`;
    case 'fr-FR':
      return `${teamName} vous propose un nouveau contrat de ${years} an(s) avec un salaire de ${wageStr} par semaine.`;
    case 'en-GB':
    default:
      return `${teamName} have offered you a new ${years}-year contract with weekly wages of ${wageStr}.`;
  }
}

export function getCurrentLanguage(): LanguageCode {
  return currentLanguage;
}

