export function generateLocalizedManagerMessage(
  managerName: string,
  teamName: string,
  playerName: string,
  type: 'praise' | 'warning' | 'promotion'
): string {
  switch (type) {
    case 'promotion':
      switch (currentLanguage) {
        case 'es-ES':
          return `El míster ${managerName} de ${teamName}: "${playerName}, tu rendimiento constante te ha asegurado la titularidad en el equipo."`;
        case 'es-AR':
          return `El DT ${managerName} de ${teamName}: "Che ${playerName}, respondiste bárbaro en la cancha. Vas de titular el próximo partido."`;
        case 'pt-BR':
          return `O técnico ${managerName} do ${teamName}: "${playerName}, seu excelente desempenho garantiu sua vaga entre os titulares."`;
        case 'fr-FR':
          return `L'entraîneur ${managerName} de ${teamName} : "${playerName}, vos excellentes prestations vous ouvrent les portes du onze titulaire."`;
        case 'en-GB':
        default:
          return `Head Coach ${managerName} of ${teamName}: "${playerName}, your outstanding training work has earned you a starting XI place."`;
      }
    case 'warning':
      switch (currentLanguage) {
        case 'es-ES':
          return `El entrenador ${managerName} de ${teamName}: "${playerName}, necesitas mejorar tu disciplina táctica y forma física."`;
        case 'es-AR':
          return `El DT ${managerName} de ${teamName}: "${playerName}, ponete las pilas con el entrenamiento físico porque estás perdiendo terreno."`;
        case 'pt-BR':
          return `O técnico ${managerName} do ${teamName}: "${playerName}, você precisa focar mais na preparação física e disciplina."`;
        case 'fr-FR':
          return `L'entraîneur ${managerName} de ${teamName} : "${playerName}, vous devez hausser votre niveau d'exigence à l'entraînement."`;
        case 'en-GB':
        default:
          return `Head Coach ${managerName} of ${teamName}: "${playerName}, you need to step up your fitness and tactical discipline."`;
      }
    case 'praise':
    default:
      switch (currentLanguage) {
        case 'es-ES':
          return `El míster ${managerName} de ${teamName}: "Gran trabajo hoy, ${playerName}. Sigue demostrando esa calidad."`;
        case 'es-AR':
          return `El DT ${managerName} de ${teamName}: "¡Un partidazo ${playerName}! Seguí jugando así que sos clave para el equipo."`;
        case 'pt-BR':
          return `O técnico ${managerName} do ${teamName}: "Excelente partida, ${playerName}. Continue demonstrando essa categoria."`;
        case 'fr-FR':
          return `L'entraîneur ${managerName} de ${teamName} : "Superbe match ${playerName}. Continuez sur cette lancée !"`;
        case 'en-GB':
        default:
          return `Head Coach ${managerName} of ${teamName}: "Great performance today, ${playerName}. Keep showing that elite quality."`;
      }
  }
}

