export function translateTrainingGroupStats(stats: string[], lang: LanguageCode = currentLanguage): string {
  return stats.map((s) => translateAttributeName(s, lang)).join(', ');
}

export function translateCompetitionType(compType: string, lang: LanguageCode = currentLanguage): string {
  const map: Record<string, Record<LanguageCode, string>> = {
    league: { 'en-GB': 'League', 'es-ES': 'Liga', 'es-AR': 'Liga', 'pt-BR': 'Liga', 'fr-FR': 'Championnat' },
    cup: { 'en-GB': 'Cup', 'es-ES': 'Copa', 'es-AR': 'Copa', 'pt-BR': 'Copa', 'fr-FR': 'Coupe' },
    continental: { 'en-GB': 'Continental', 'es-ES': 'Continental', 'es-AR': 'Continental', 'pt-BR': 'Continental', 'fr-FR': 'Continental' },
    national_team: { 'en-GB': 'National Team', 'es-ES': 'Selección', 'es-AR': 'Selección', 'pt-BR': 'Seleção', 'fr-FR': 'Sélection' },
    youth_cup: { 'en-GB': 'Youth Cup', 'es-ES': 'Copa Juvenil', 'es-AR': 'Copa Juvenil', 'pt-BR': 'Copa de Base', 'fr-FR': 'Coupe Jeunes' },
    other: { 'en-GB': 'Tournament', 'es-ES': 'Torneo', 'es-AR': 'Torneo', 'pt-BR': 'Torneio', 'fr-FR': 'Tournoi' },
  };
  return map[compType]?.[lang] || compType;
}

export function translateStageReached(stage: string | undefined, lang: LanguageCode = currentLanguage): string {
  if (!stage) return '';
  if (stage.includes('Champions') || stage.includes('Winner')) {
    switch (lang) {
      case 'es-ES': return 'Campeón 🏆';
      case 'es-AR': return 'Campeón 🏆';
      case 'pt-BR': return 'Campeão 🏆';
      case 'fr-FR': return 'Champion 🏆';
      default: return stage;
    }
  }
  if (stage.includes('Runner-up') || stage.includes('Finalist')) {
    switch (lang) {
      case 'es-ES': return 'Subcampeón 🥈';
      case 'es-AR': return 'Subcampeón 🥈';
      case 'pt-BR': return 'Vice-campeão 🥈';
      case 'fr-FR': return 'Finaliste 🥈';
      default: return stage;
    }
  }
  if (stage.includes('Semi-Final')) {
    switch (lang) {
      case 'es-ES': return 'Semifinales';
      case 'es-AR': return 'Semifinales';
      case 'pt-BR': return 'Semifinal';
      case 'fr-FR': return 'Demi-Finale';
      default: return stage;
    }
  }
  if (stage.includes('Quarter-Final')) {
    switch (lang) {
      case 'es-ES': return 'Cuartos de Final';
      case 'es-AR': return 'Cuartos de Final';
      case 'pt-BR': return 'Quartas de Final';
      case 'fr-FR': return 'Quarts de Finale';
      default: return stage;
    }
  }
  if (stage.includes('Rank #')) {
    const num = stage.replace('Rank #', '').trim();
    switch (lang) {
      case 'es-ES': return `Posición #${num}`;
      case 'es-AR': return `Puesto #${num}`;
      case 'pt-BR': return `Posição #${num}`;
      case 'fr-FR': return `Rang #${num}`;
      default: return stage;
    }
  }
  return stage;
}

export function translateQualificationBadge(label: string, type?: string, lang: LanguageCode = currentLanguage): string {
  if (!label) return '';
  if (type === 'youth_intl_cup' || label.includes("Int'l Youth Cup")) {
    switch (lang) {
      case 'es-ES': return 'Copa Juvenil Internacional';
      case 'es-AR': return 'Copa Internacional Juvenil';
      case 'pt-BR': return 'Copa Internacional de Base';
      case 'fr-FR': return 'Coupe Internationale Junior';
      default: return label;
    }
  }
  if (type === 'promotion_auto' || label.includes('Promotion') && label.includes('1st')) {
    switch (lang) {
      case 'es-ES': return 'Ascenso Directo a 1ª';
      case 'es-AR': return 'Ascenso Directo a 1ª';
      case 'pt-BR': return 'Acesso Direto à 1ª Divisão';
      case 'fr-FR': return 'Promotion Directe en D1';
      default: return label;
    }
  }
  if (type === 'promotion_playoff' || label.includes('Promotion Playoff')) {
    switch (lang) {
      case 'es-ES': return 'Playoff de Ascenso';
      case 'es-AR': return 'Reducido de Ascenso';
      case 'pt-BR': return 'Playoff de Acesso';
      case 'fr-FR': return 'Barrages de Promotion';
      default: return label;
    }
  }
  if (type === 'relegation_direct' || label.includes('Relegation to 2nd') || label.includes('Relegated')) {
    switch (lang) {
      case 'es-ES': return 'Descenso a 2ª División';
      case 'es-AR': return 'Descenso a 2ª División';
      case 'pt-BR': return 'Rebaixamento para a 2ª';
      case 'fr-FR': return 'Relégation en D2';
      default: return label;
    }
  }
  if (type === 'relegation_playoff' || label.includes('Relegation Playoff')) {
    switch (lang) {
      case 'es-ES': return 'Playoff de Descenso';
      case 'es-AR': return 'Promoción por la Permanencia';
      case 'pt-BR': return 'Playoff de Rebaixamento';
      case 'fr-FR': return 'Barrages de Maintien';
      default: return label;
    }
  }
  if (label.includes('Mid-Table') || label.includes('First Division Safe') || label.includes('Safe')) {
    switch (lang) {
      case 'es-ES': return 'Permanencia Asegurada';
      case 'es-AR': return 'Permanencia Asegurada';
      case 'pt-BR': return 'Meio de Tabela / Seguro';
      case 'fr-FR': return 'Maintien Assuré';
      default: return label;
    }
  }
  if (label.includes('Youth League')) {
    switch (lang) {
      case 'es-ES': return 'Liga de Cantera';
      case 'es-AR': return 'Liga de Juveniles';
      case 'pt-BR': return 'Liga de Base';
      case 'fr-FR': return 'Ligue de Formation';
      default: return label;
    }
  }
  return label;
}


